import unittest

from hourglass.models import Span
from hourglass.rounding import label_rounded_spans, round_span


class RoundSpanTests(unittest.TestCase):
    def test_rounds_to_nearest_step(self):
        result = round_span(Span(9 * 60 + 7, 17 * 60 + 8), 15)
        self.assertEqual(result, Span(9 * 60, 17 * 60 + 15))

    def test_exact_half_rounds_up(self):
        self.assertEqual(round_span(Span(67, 120), 15), Span(60, 120))
        self.assertEqual(round_span(Span(68, 120), 15), Span(75, 120))

    def test_end_of_day_is_kept(self):
        self.assertEqual(round_span(Span(0, 1439), 15), Span(0, 1440))

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 545), 15)


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 14)]
        self.assertEqual(label_rounded_spans(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_one_label_per_span_in_order(self):
        spans = [Span(600, 660), Span(60, 100)]
        labels = label_rounded_spans(spans, 30)
        self.assertEqual(labels, ["10:00-11:00 (1h 0m)", "01:00-01:30 (0h 30m)"])

    def test_empty_input(self):
        self.assertEqual(label_rounded_spans([], 15), [])


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -5, 7, 45, 120):
            with self.assertRaises(ValueError):
                label_rounded_spans([Span(0, 60)], step)

    def test_bad_step_raises_even_without_spans(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([], 0)

    def test_good_steps_accepted(self):
        for step in (1, 5, 10, 15, 20, 30, 60):
            self.assertEqual(len(label_rounded_spans([Span(0, 120)], step)), 1)
